// Map a GitHub pull_request event to a Linear action.
// Output is empty when no action is needed.
const event = $input.first().json;
const body = event.body ?? event;
const pr = body.pull_request;
if (!pr) return [];
const action = body.action;
const branch = (pr.head && pr.head.ref) || '';
const title = pr.title || '';
const match = branch.match(/dwn-(\d+)/i) || title.match(/\bDWN-(\d+)\b/i);
if (!match) return [];
const issueNumber = Number(match[1]);
let targetState = null;
if (action === 'opened' || action === 'reopened') targetState = pr.draft ? 'In Progress' : 'In Review';
else if (action === 'ready_for_review') targetState = 'In Review';
else if (action === 'converted_to_draft') targetState = 'In Progress';
else if (action === 'closed' && pr.merged) targetState = 'Done';
if (!targetState) return [];
const graphqlQuery =
  'query { issues(filter: { team: { key: { eq: "DWN" } }, number: { eq: ' + issueNumber + ' } }) ' +
  '{ nodes { id identifier team { states { nodes { id name } } } } } }';
return [{ json: { issueNumber, targetState, prUrl: pr.html_url, prTitle: title, action, graphqlQuery } }];

// Pick the issue UUID and the target state UUID from the GraphQL response.
const plan = $('Map PR Event').first().json;
const resp = $input.first().json;
const issues = (resp.data && resp.data.issues && resp.data.issues.nodes) || [];
if (!issues.length) return [];
const issue = issues[0];
const states = (issue.team && issue.team.states && issue.team.states.nodes) || [];
const state = states.find((s) => s.name === plan.targetState);
if (!state) return [];
return [{ json: { issueId: issue.id, identifier: issue.identifier, stateId: state.id, prUrl: plan.prUrl, prTitle: plan.prTitle, targetState: plan.targetState } }];
